const close = (actual, exp) => Math.abs(actual - exp) <= 1e-6 * Math.max(1, Math.abs(exp));

test("Duration#normalize can convert all unit pairs", () => {
  const failures = [];

  for (const from of units) {
    for (const to of units) {
      const exp = expected[from][to];
      const dur = Duration.fromObject({ [from]: 1 });

      const asValue = dur.as(to);
      if (!close(asValue, exp)) {
        failures.push(`as: ${from} -> ${to}: expected ${exp}, got ${asValue}`);
      }

      const shifted = dur.shiftTo(to);
      if (!close(shifted.get(to), exp)) {
        failures.push(`shiftTo: ${from} -> ${to}: expected ${exp}, got ${shifted.get(to)}`);
      }

      const normalized = dur
        .shiftTo(to)
        .normalize()
        .get(to);
      if (!close(normalized, exp)) {
        failures.push(`normalize: ${from} -> ${to}: expected ${exp}, got ${normalized}`);
      }

      // round trip back to the original unit must recover the original value
      const roundTrip = dur
        .shiftTo(to)
        .shiftTo(from)
        .get(from);
      if (!close(roundTrip, 1)) {
        failures.push(`round trip: ${from} -> ${to} -> ${from}: expected 1, got ${roundTrip}`);
      }
    }
  }

  expect(failures).toEqual([]);
});

